/*updateDivsnDeliveryPlanAlterPors*/
UPDATE ICOMPORS
SET
	STATUS = 'D'
WHERE
		BUYER  = #{buyer}
	AND PO_NO  = #{po_no}
	AND PO_SEQ = #{po_seq}
	AND STATUS != 'D'


/*updateDivsnDeliveryPlanAlterPodt*/
UPDATE ICOMPODT
SET
	  DS_DATE = #{max_cd_date}
WHERE
		BUYER  = #{buyer}
	AND PO_NO  = #{po_no}
	AND PO_SEQ = #{po_seq}
